CREATE TRIGGER sync_state_hashes_insert AFTER INSERT ON entries BEGIN
    DELETE FROM sync_state_hashes;
END;
CREATE TRIGGER sync_state_hashes_update AFTER UPDATE ON entries BEGIN
    DELETE FROM sync_state_hashes;
END;
CREATE TRIGGER sync_state_hashes_delete AFTER DELETE ON entries BEGIN
    DELETE FROM sync_state_hashes;
END;
CREATE TRIGGER sync_rows_changed_insert AFTER INSERT ON entries BEGIN
    INSERT OR IGNORE INTO sync_rows_changed (hid) VALUES (NEW.hid);
END;
CREATE TRIGGER sync_rows_changed_update AFTER UPDATE ON entries BEGIN
    INSERT OR IGNORE INTO sync_rows_changed (hid) VALUES (OLD.hid), (NEW.hid);
END;
CREATE TRIGGER sync_rows_changed_delete AFTER DELETE ON entries BEGIN
    INSERT OR IGNORE INTO sync_rows_changed (hid) VALUES (OLD.hid);
END;
CREATE TRIGGER stats_cache_insert AFTER INSERT ON entries BEGIN
    INSERT INTO stats_cache_dirty (field, dur, at)
        SELECT new.field, coalesce(new.dur, ''), new.occur_time WHERE new.occur_time IS NOT NULL
        UNION ALL SELECT substr(new.slug, 6), '', '' WHERE new.field = 'spec'
        UNION ALL SELECT '', '', new.occur_time
            WHERE new.occur_time_tz IS NOT NULL AND new.deleted_at IS NULL
              AND new.superseded_by IS NULL
              AND new.field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
              AND new.occur_time_tz IS NOT (
                  SELECT occur_time_tz FROM entries
                   WHERE occur_time_tz IS NOT NULL AND deleted_at IS NULL
                     AND superseded_by IS NULL
                     AND field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
                     AND occur_time < new.occur_time AND rowid <> new.rowid
                   ORDER BY occur_time DESC LIMIT 1)
        ON CONFLICT (field, dur) DO UPDATE SET at = excluded.at WHERE excluded.at < at;
END;
CREATE TRIGGER stats_cache_update AFTER UPDATE ON entries BEGIN
    INSERT INTO stats_cache_dirty (field, dur, at)
        SELECT old.field, coalesce(old.dur, ''), old.occur_time WHERE old.occur_time IS NOT NULL
        UNION ALL SELECT substr(old.slug, 6), '', '' WHERE old.field = 'spec'
        UNION ALL SELECT '', '', old.occur_time
            WHERE old.occur_time_tz IS NOT NULL AND old.deleted_at IS NULL
              AND old.superseded_by IS NULL
              AND old.field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
              AND old.occur_time_tz IS NOT (
                  SELECT occur_time_tz FROM entries
                   WHERE occur_time_tz IS NOT NULL AND deleted_at IS NULL
                     AND superseded_by IS NULL
                     AND field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
                     AND occur_time < old.occur_time AND rowid <> old.rowid
                   ORDER BY occur_time DESC LIMIT 1)
        UNION ALL
        SELECT new.field, coalesce(new.dur, ''), new.occur_time WHERE new.occur_time IS NOT NULL
        UNION ALL SELECT substr(new.slug, 6), '', '' WHERE new.field = 'spec'
        UNION ALL SELECT '', '', new.occur_time
            WHERE new.occur_time_tz IS NOT NULL AND new.deleted_at IS NULL
              AND new.superseded_by IS NULL
              AND new.field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
              AND new.occur_time_tz IS NOT (
                  SELECT occur_time_tz FROM entries
                   WHERE occur_time_tz IS NOT NULL AND deleted_at IS NULL
                     AND superseded_by IS NULL
                     AND field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
                     AND occur_time < new.occur_time AND rowid <> new.rowid
                   ORDER BY occur_time DESC LIMIT 1)
        ON CONFLICT (field, dur) DO UPDATE SET at = excluded.at WHERE excluded.at < at;
END;
CREATE TRIGGER stats_cache_delete AFTER DELETE ON entries BEGIN
    INSERT INTO stats_cache_dirty (field, dur, at)
        SELECT old.field, coalesce(old.dur, ''), old.occur_time WHERE old.occur_time IS NOT NULL
        UNION ALL SELECT substr(old.slug, 6), '', '' WHERE old.field = 'spec'
        UNION ALL SELECT '', '', old.occur_time
            WHERE old.occur_time_tz IS NOT NULL AND old.deleted_at IS NULL
              AND old.superseded_by IS NULL
              AND old.field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
              AND old.occur_time_tz IS NOT (
                  SELECT occur_time_tz FROM entries
                   WHERE occur_time_tz IS NOT NULL AND deleted_at IS NULL
                     AND superseded_by IS NULL
                     AND field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit')
                     AND occur_time < old.occur_time AND rowid <> old.rowid
                   ORDER BY occur_time DESC LIMIT 1)
        ON CONFLICT (field, dur) DO UPDATE SET at = excluded.at WHERE excluded.at < at;
END;
CREATE TRIGGER spec_alias_names_insert AFTER INSERT ON entries
WHEN new.field = 'spec' BEGIN
    INSERT OR IGNORE INTO spec_alias_names
        SELECT json_extract(new.data, fullkey || '.state') AS name, new.rowid
          FROM json_each(CASE WHEN json_valid(new.data) THEN new.data END, '$.derived_aliases')
         WHERE name IS NOT NULL;
END;
CREATE TRIGGER spec_alias_names_update AFTER UPDATE ON entries
WHEN old.field = 'spec' OR new.field = 'spec' BEGIN
    DELETE FROM spec_alias_names WHERE spec = old.rowid;
    INSERT OR IGNORE INTO spec_alias_names
        SELECT json_extract(new.data, fullkey || '.state') AS name, new.rowid
          FROM json_each(CASE WHEN new.field = 'spec' AND json_valid(new.data) THEN new.data END,
                         '$.derived_aliases')
         WHERE name IS NOT NULL;
END;
CREATE TRIGGER spec_alias_names_delete AFTER DELETE ON entries
WHEN old.field = 'spec' BEGIN
    DELETE FROM spec_alias_names WHERE spec = old.rowid;
END;
CREATE TRIGGER check_changes_cap AFTER INSERT ON check_changes
    WHEN new.seq % 1024 = 0 BEGIN
    DELETE FROM check_changes WHERE seq <= new.seq - 32768;
END;
CREATE TRIGGER check_changes_insert AFTER INSERT ON entries BEGIN
    INSERT INTO check_changes (hid, field, at)
        VALUES (new.hid, new.field, coalesce(new.occur_time, ''));
END;
CREATE TRIGGER check_changes_update AFTER UPDATE ON entries BEGIN
    INSERT INTO check_changes (hid, field, at)
        SELECT old.hid, old.field, coalesce(old.occur_time, '')
        UNION SELECT new.hid, new.field, coalesce(new.occur_time, '');
END;
CREATE TRIGGER check_changes_delete AFTER DELETE ON entries BEGIN
    INSERT INTO check_changes (hid, field, at)
        VALUES (old.hid, old.field, coalesce(old.occur_time, ''));
END;
CREATE TRIGGER check_changes_op_insert AFTER INSERT ON ops
    WHEN new.applied = 1 OR new.hid = '~chain' BEGIN
    INSERT INTO check_changes (hid, field, at) VALUES (new.hid, '', '');
END;
CREATE TRIGGER check_changes_op_update AFTER UPDATE ON ops
    WHEN old.applied IS NOT new.applied OR old.body IS NOT new.body BEGIN
    INSERT INTO check_changes (hid, field, at)
        SELECT old.hid, '', '' UNION SELECT new.hid, '', '';
END;
CREATE TRIGGER check_changes_op_delete AFTER DELETE ON ops
    WHEN old.applied = 1 OR old.hid = '~chain' BEGIN
    INSERT INTO check_changes (hid, field, at) VALUES (old.hid, '', '');
END;
CREATE UNIQUE INDEX entries_slug
    ON entries (slug)
    WHERE superseded_by IS NULL;
CREATE INDEX entries_slug_lookup
    ON entries (slug);
CREATE UNIQUE INDEX entries_field_occurtime
    ON entries (field, occur_time)
    WHERE occur_time IS NOT NULL AND deleted_at IS NULL AND superseded_by IS NULL
      AND state IS NOT NULL;
CREATE INDEX entries_superseded_by
    ON entries (superseded_by)
    WHERE superseded_by IS NOT NULL;
CREATE INDEX entries_conflicts
    ON entries (hid)
    WHERE conflicts IS NOT NULL;
CREATE INDEX entries_spec_templates
    ON entries (slug)
    WHERE field = 'spec' AND slug GLOB '*%*%*';
CREATE INDEX entries_field_occur
    ON entries (field, occur_time DESC);
CREATE INDEX entries_live_field_occur
    ON entries (field, occur_time, slug)
    WHERE deleted_at IS NULL;
CREATE INDEX entries_field_state
    ON entries (field, occur_time, slug)
    WHERE occur_time IS NOT NULL AND deleted_at IS NULL AND superseded_by IS NULL
      AND NOT (verb = 'point' AND (state IS NULL OR state = 'true'));
CREATE INDEX entries_field_deciding
    ON entries (field, occur_time, slug)
    WHERE occur_time IS NOT NULL AND deleted_at IS NULL AND superseded_by IS NULL
      AND verb <> 'point';
CREATE INDEX entries_field_blocks
    ON entries (field, occur_time, slug)
    WHERE occur_time IS NOT NULL AND deleted_at IS NULL AND superseded_by IS NULL
      AND dur IS NOT NULL
      AND verb <> 'point';
CREATE INDEX entries_field_states
    ON entries (field, state)
    WHERE deleted_at IS NULL AND superseded_by IS NULL AND state IS NOT NULL
      AND json_extract(COALESCE(extra_metadata, '{}'), '$.track') IS NULL;
CREATE INDEX entries_content_hash
    ON entries (content_hash);
CREATE INDEX entries_verb ON entries (verb);
CREATE INDEX entries_modify_time_ms
    ON entries (modify_time_ms);
CREATE INDEX entries_occur_time
    ON entries (occur_time, slug)
    WHERE deleted_at IS NULL;
CREATE INDEX entries_hybrid
    ON entries (COALESCE(occur_time, create_time), slug)
    WHERE deleted_at IS NULL;
CREATE INDEX entries_live_field_hybrid
    ON entries (field, COALESCE(occur_time, create_time), slug)
    WHERE deleted_at IS NULL;
CREATE INDEX entries_id_structure
    ON entries (hid) WHERE id_structure IS NOT NULL;
CREATE INDEX entries_field_structure
    ON entries (hid) WHERE field_structure IS NOT NULL;
CREATE INDEX entry_history_entry
    ON entry_history(entry_hid, version DESC);
CREATE INDEX entry_history_change_kind
    ON entry_history(change_kind);
CREATE INDEX entry_history_action
    ON entry_history(action_id) WHERE action_id IS NOT NULL;
CREATE INDEX undo_actions_undone
    ON undo_actions(id) WHERE undone = 1;
CREATE INDEX ops_hid ON ops(hid);
CREATE INDEX ops_slug ON ops(slug);
CREATE INDEX ops_hlc ON ops(hlc);
CREATE INDEX ops_held ON ops(endpoint, seq) WHERE applied = 0;
CREATE INDEX integrity_warnings_hid ON integrity_warnings(hid);
CREATE INDEX integrity_warnings_slug ON integrity_warnings(entry_slug);
CREATE INDEX integrity_warnings_pending
    ON integrity_warnings(detected_at) WHERE resolution IS NULL;
CREATE INDEX entries_zoned
    ON entries (occur_time, occur_time_tz)
    WHERE occur_time_tz IS NOT NULL AND deleted_at IS NULL AND superseded_by IS NULL
      AND field NOT IN ('spec', 'layout', 'alias', 'view', 'command', 'index', 'kit');
CREATE INDEX spec_alias_names_spec ON spec_alias_names (spec);
CREATE INDEX entries_asserted_base
    ON entries (field)
    WHERE deleted_at IS NULL AND superseded_by IS NULL
      AND json_type(extra_metadata, '$.asserted_base') = 'object';
CREATE INDEX "kit_oldkit__oldkit_time" ON entries(field, occur_time);
